from .units import MAX_TOTAL_G, WeightError, kg_to_g, g_to_kg

MAX_TOTAL_KG = g_to_kg(MAX_TOTAL_G)  # the carrier system stores grams in a signed 32-bit column


def check_total_kg(weight_kg):
    grams = kg_to_g(weight_kg)
    if grams > MAX_TOTAL_G:
        raise WeightError("total weight exceeds the carrier limit")
    return g_to_kg(grams)
